<script setup lang="ts">
import { onMounted, ref } from 'vue'; import type { OrderSummary } from '@cyberboard/types'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { getApiErrorMessage, normalizeList, portalApi } from '../api'
const loading=ref(true); const error=ref(''); const orders=ref<OrderSummary[]>([]); const money=(cents:number,currency:string)=>`${(cents/100).toFixed(2)} ${currency}`
async function load(){loading.value=true;error.value='';try{orders.value=normalizeList(await portalApi.listOrders({page:1,pageSize:20}))}catch(cause){orders.value=[];error.value=getApiErrorMessage(cause)}finally{loading.value=false}};onMounted(load)
</script>
<template><div class="portal-heading"><div><p class="eyebrow">账单记录</p><h1>订单</h1><p>查看套餐订单和支付状态。</p></div><button class="button button--secondary" type="button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div><section class="portal-panel"><StatePanel v-if="loading" title="正在加载订单" description="正在读取订单记录。"/><StatePanel v-else-if="error" title="订单加载失败" :description="error" action-label="重试" @action="load"/><StatePanel v-else-if="!orders.length" title="暂无订单" description="服务端尚未返回订单记录。"/><div v-else class="table-wrap"><table><thead><tr><th>订单</th><th>套餐</th><th>金额</th><th>状态</th><th>创建时间</th><th>支付时间</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td class="mono">{{order.id}}</td><td>{{order.plan}}</td><td>{{money(order.amountCents,order.currency)}}</td><td>{{order.status}}</td><td>{{order.createdAt}}</td><td>{{order.paidAt??'—'}}</td></tr></tbody></table></div></section></template>
